def isi_modal_rata(apps, schema_editor):
    """Awalnya modal rata = modal terakhir (item.cost_amount).

    Tabel item milik POS; di database pengembangan yang masih kosong tabel itu
    belum ada, jadi langkah ini dilewati.
    """
    koneksi = schema_editor.connection
    if "item" not in koneksi.introspection.table_names():
        return
    VarianInfo = apps.get_model("master", "VarianInfo")
    with koneksi.cursor() as cursor:
        cursor.execute("SELECT item_name, variant, cost_amount FROM item")
        modal = {(n, v): m for n, v, m in cursor.fetchall()}
    daftar = list(VarianInfo.objects.filter(modal_rata__isnull=True))
    for info in daftar:
        info.modal_rata = modal.get((info.item_name, info.variant))
    VarianInfo.objects.bulk_update(daftar, ["modal_rata"], batch_size=500)


